// Microsoft SharePoint, im Namen der fragenden Person.
//
// Mit Sites.Selected gilt die Schnittmenge: die Anwendung darf nur die von der
// IT freigegebenen Bereiche, und darin nur das, was die fragende Person selbst
// sehen darf. Ein 403 ist hier deshalb kein Fehler, sondern eine Auskunft.

const input = { ...$input.first().json };
for (const _k of Object.keys(input)) { if (input[_k] === '' || input[_k] === null) delete input[_k]; }
const action = input.action || '';
const caller = String(input.caller || '').trim();

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pg = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };
const GRAPH = 'https://graph.microsoft.com/v1.0';
function fail(m) { return [{ json: { error: m, fertig: true } }]; }

const credRows = await helpers.httpRequest({ method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.microsoft&select=cred_key,cred_value',
  headers: pg, json: true });
const cred = {}; for (const c of (credRows || [])) cred[c.cred_key] = c.cred_value;
for (const need of ['tenant_id','client_id','client_secret','token_key','redirect_uri'])
  if (!cred[need]) return fail('Microsoft ist nicht eingerichtet, es fehlt: ' + need);
const connectUrl = String(cred.redirect_uri).replace('ms-oauth-callback', 'ms-connect');

let bereiche = [];
try { bereiche = JSON.parse(cred.sharepoint_sites || '[]'); } catch (e) {}
if (!bereiche.length) return fail('Es ist kein SharePoint-Bereich freigegeben. Die Freigabe erfolgt je Bereich durch die IT.');

if (!caller) return fail('Kein Nutzerbezug vorhanden. SharePoint-Zugriff geht nur im Namen einer angemeldeten Person.');

let personKey = caller;
if (!caller.startsWith('entra:')) {
  try {
    const map = await helpers.httpRequest({ method: 'GET',
      url: SUPABASE_URL + '/rest/v1/user_identity_map?legacy_key=eq.' + encodeURIComponent(caller) + '&select=entra_key',
      headers: pg, json: true });
    if (map && map[0] && map[0].entra_key) personKey = map[0].entra_key;
  } catch (e) {}
}

async function accessToken() {
  const rows = await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/get_user_token',
    headers: pg, json: true,
    body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_key: cred.token_key }) });
  const row = rows && rows[0];
  if (!row) return { error: 'Fuer diese Person ist noch kein Microsoft-Konto verbunden. Einmalig verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  if (row.status !== 'connected') return { error: 'Die Verbindung ist unterbrochen (' + row.status + '). Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  if (new Date(row.expires_at).getTime() - Date.now() > 5 * 60 * 1000) return { token: row.access_token };
  if (!row.refresh_token) return { error: 'Der Zugang ist abgelaufen. Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  let tok;
  try {
    tok = await helpers.httpRequest({ method: 'POST',
      url: 'https://login.microsoftonline.com/' + encodeURIComponent(cred.tenant_id) + '/oauth2/v2.0/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, json: true,
      body: 'client_id=' + encodeURIComponent(cred.client_id) + '&client_secret=' + encodeURIComponent(cred.client_secret) +
            '&refresh_token=' + encodeURIComponent(row.refresh_token) + '&grant_type=refresh_token&scope=' + encodeURIComponent(row.scopes || '') });
  } catch (e) {
    const b = (e && e.response && e.response.body) ? JSON.stringify(e.response.body) : String(e.message || e);
    const code = (b.match(/AADSTS\d+/) || ['unbekannt'])[0];
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/mark_user_token', headers: pg,
      body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_status: 'reconnect_required', p_detail: code }) });
    return { error: 'Die Verbindung ist beendet (' + code + '). Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  }
  await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/upsert_user_token', headers: pg,
    body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_key: cred.token_key,
      p_access_token: tok.access_token, p_refresh_token: tok.refresh_token || '',
      p_expires_at: new Date(Date.now() + ((tok.expires_in || 3600) * 1000)).toISOString(),
      p_scopes: tok.scope || row.scopes || null, p_account_id: row.account_id || '' }) });
  return { token: tok.access_token };
}

const t = await accessToken();
if (t.error) return fail(t.error);
const H = { Authorization: 'Bearer ' + t.token };

function errText(e) {
  const b = e && e.response && e.response.body;
  if (b && b.error && b.error.message) return b.error.message;
  const s = String((e && e.message) || e);
  if (/40[13]/.test(s)) return 'Zugriff verweigert. Entweder ist der Bereich nicht freigegeben, oder die fragende Person hat dort selbst keine Rechte.';
  return s;
}
function bereichFinden(name) {
  if (!name) return bereiche[0];
  const n = String(name).toLowerCase();
  return bereiche.find(function (b) { return String(b.name).toLowerCase().indexOf(n) >= 0; }) || null;
}
function groesse(n) { return n >= 1048576 ? (n / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(n / 1024)) + ' KB'; }
function zeile(it) {
  const art = it.folder ? '[Ordner]' : '[' + groesse(it.size || 0) + ']';
  return '- ' + art + ' ' + it.name + (it.folder ? '/' : '') +
         '  geaendert ' + String(it.lastModifiedDateTime || '').replace('T', ' ').slice(0, 16) +
         (it.folder ? '' : '  (id: ' + it.id + ')');
}

try {
  if (action === 'list_sites') {
    return [{ json: { fertig: true, result: 'Freigegebene Bereiche:\n' +
      bereiche.map(function (b) { return '- ' + b.name; }).join('\n') +
      '\n\nWeitere Bereiche muss die IT einzeln freigeben.' } }];
  }

  if (action === 'list_files') {
    const b = bereichFinden(input.site);
    if (!b) return fail('Bereich nicht freigegeben. Verfuegbar: ' + bereiche.map(function (x) { return x.name; }).join(', '));
    const pfad = String(input.path || '').replace(/^\/+|\/+$/g, '');
    const basis = pfad
      ? GRAPH + '/sites/' + b.id + '/drive/root:/' + encodeURI(pfad) + ':/children'
      : GRAPH + '/sites/' + b.id + '/drive/root/children';
    const r = await helpers.httpRequest({ method: 'GET',
      url: basis + '?$top=50&$select=id,name,size,folder,lastModifiedDateTime', headers: H, json: true });
    const items = (r && r.value) || [];
    if (!items.length) return [{ json: { fertig: true, result: 'In "' + b.name + (pfad ? '/' + pfad : '') + '" liegt nichts.' } }];
    return [{ json: { fertig: true, result: b.name + (pfad ? '/' + pfad : '') + ', ' + items.length + ' Eintraege:\n' + items.map(zeile).join('\n') } }];
  }

  if (action === 'search_files') {
    if (!input.query) return fail('Parameter "query" ist noetig.');
    const b = bereichFinden(input.site);
    if (!b) return fail('Bereich nicht freigegeben. Verfuegbar: ' + bereiche.map(function (x) { return x.name; }).join(', '));
    const q = encodeURIComponent(String(input.query).split("'").join(''));
    const r = await helpers.httpRequest({ method: 'GET',
      url: GRAPH + '/sites/' + b.id + '/drive/root/search(q=%27' + q + '%27)?$top=25&$select=id,name,size,folder,lastModifiedDateTime',
      headers: H, json: true });
    const items = (r && r.value) || [];
    if (!items.length) return [{ json: { fertig: true, result: 'Nichts gefunden zu "' + input.query + '" in "' + b.name + '".' } }];
    return [{ json: { fertig: true, result: items.length + ' Treffer in "' + b.name + '":\n' + items.map(zeile).join('\n') } }];
  }

  if (action === 'read_file') {
    if (!input.file_id) return fail('Parameter "file_id" ist noetig, die id steht bei jeder Datei aus list_files oder search_files.');
    const b = bereichFinden(input.site);
    if (!b) return fail('Bereich nicht freigegeben. Verfuegbar: ' + bereiche.map(function (x) { return x.name; }).join(', '));
    const meta = await helpers.httpRequest({ method: 'GET',
      url: GRAPH + '/sites/' + b.id + '/drive/items/' + encodeURIComponent(input.file_id) + '?$select=id,name,size,file,webUrl',
      headers: H, json: true });
    const name = meta.name || '';
    if (/\.(txt|md|csv|json|xml|html?|log)$/i.test(name)) {
      const roh = await helpers.httpRequest({ method: 'GET',
        url: GRAPH + '/sites/' + b.id + '/drive/items/' + encodeURIComponent(input.file_id) + '/content',
        headers: H, json: false });
      return [{ json: { fertig: true, result: 'Datei "' + name + '":\n\n' + String(roh).slice(0, 6000) } }];
    }
    // Word, PowerPoint, Excel und PDF: Microsoft wandelt selbst nach PDF um, den
    // Text zieht danach der Extract-Baustein heraus. Ohne diesen Umweg muesste
    // der Skill Dateiformate selbst auspacken, wofuer im Code-Baustein die
    // Bibliotheken fehlen.
    const bin = await helpers.httpRequest({ method: 'GET',
      url: GRAPH + '/sites/' + b.id + '/drive/items/' + encodeURIComponent(input.file_id) + '/content?format=pdf',
      headers: H, encoding: 'arraybuffer' });
    const daten = await this.helpers.prepareBinaryData(Buffer.from(bin), name.replace(/\.[^.]+$/, '') + '.pdf', 'application/pdf');
    return [{ json: { fertig: false, dateiname: name, webUrl: meta.webUrl || '' }, binary: { data: daten } }];
  }

  return fail('Unbekannte Aktion "' + action + '". Moeglich: list_sites, list_files, search_files, read_file.');
} catch (e) {
  return fail('SharePoint (' + action + '): ' + errText(e));
}

// Text aus der umgewandelten PDF zusammenfassen.
const j = $input.first().json;
const vor = $('SharePoint Logic').first().json;
const text = String(j.text || j.data || '').replace(/\n{3,}/g, '\n\n').trim();
if (!text) {
  return [{ json: { result: 'Die Datei "' + (vor.dateiname || '') + '" liess sich nicht in Text umwandeln. Sie liegt hier: ' + (vor.webUrl || '') } }];
}
return [{ json: { result: 'Datei "' + (vor.dateiname || '') + '" (' + text.length + ' Zeichen):\n\n' + text.slice(0, 6000) } }];
